overflow-x:hidden;padding:2px 2px 4px 0}\n.ft{flex:none;display:flex;align-items:center;gap:6px}\n.ft .btn{flex:1 1 0}\n.ft .sec{flex:none}\n.ft .sec .btn{flex:none}\n.err{flex:none;padding:4px 8px;border:1px solid var(--accent-alt);border-radius:8px;background:var(--soft);font-size:11px}\n.err::before{content:\"! \";font-weight:700}\n.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.f-title,.f-date,.fgrid .pv{grid-column:1/-1}\n.fld{display:flex;flex-direction:column;gap:3px}\n.lb{font-size:11px;color:var(--muted)}\n.inp{display:block;width:100%;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font-family:inherit;font-size:13px;outline:none}\n.inp:focus{border-color:var(--accent);box-shadow:0 0 0 2px var(--soft)}\n.pv{min-height:15px;font-size:11px;color:var(--muted)}\n.card[data-size=\"6x3\"] .fgrid{grid-template-columns:repeat(4,minmax(0,1fr))}\n.card[data-size=\"6x3\"] .f-title,.card[data-size=\"6x3\"] .f-date,.card[data-size=\"6x3\"] .fgrid .pv{grid-column:span 2}\n.card[data-size=\"6x3\"] .fgrid .pv{align-self:end}\n\n.dt{display:flex;flex-direction:column;gap:8px}\n.dt-title{font-size:14px;font-weight:700;line-height:1.3;overflow-wrap:anywhere}\n.dt-prog{display:flex;align-items:center;gap:8px}\n.dt-prog .bar{flex:1 1 auto;height:8px}\n.dt-pct{flex:none;font-size:18px;font-weight:700;font-variant-numeric:tabular-nums}\n.dt-pages,.dt-last{font-size:11.5px;color:var(--muted)}\n.dt-last .badge{margin-left:6px}\n.dt-form{display:grid;grid-template-columns:1fr 1fr;gap:6px 8px}\n.dt-form .pv{grid-column:1/-1}\n.sec{display:flex;flex-wrap:wrap;align-items:center;gap:6px}\n.sec .btn{height:28px;padding:0 10px;font-size:12px}\n.ctext{font-size:11.5px;font-weight:600}\n.card[data-size=\"6x3\"] .dt{flex-direction:row;gap:14px}\n.card[data-size=\"6x3\"] .dt-info,.card[data-size=\"6x3\"] .dt-form{flex:1 1 0;display:flex;flex-direction:column;gap:6px}\n.card[data-size=\"6x3\"] .dt-form{display:grid;align-content:start}\n.card[data-size=\"6x3\"] .dt-title{font-size:13px}\n.card[data-size=\"3x3\"] .dt{gap:6px}\n.card[data-size=\"3x3\"] .dt-title{font-size:12.5px}\n.card[data-size=\"3x3\"] .dt-pct{font-size:15px}\n.card[data-size=\"3x3\"] .inp{height:30px}\n.card[data-size=\"6x6\"] .dt{gap:12px}\n.card[data-size=\"6x6\"] .dt-title{font-size:17px}\n.card[data-size=\"6x6\"] .dt-pct{font-size:22px}\n.card[data-size=\"6x6\"] .dt-prog .bar{height:10px}\n\n.hlist{display:flex;flex-direction:column;gap:6px}\n.hi{display:flex;flex-direction:column;gap:6px;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.hi-main{flex:1 1 auto}\n.hi-title{font-size:12.5px;font-weight:600;overflow-wrap:anywhere}\n.hi-meta{font-size:10.5px;color:var(--muted)}\n.hi-act{display:flex;flex-wrap:wrap;align-items:center;gap:6px}\n.hi-act .btn{height:26px;padding:0 9px;font-size:11px}\n.card[data-size=\"6x3\"] .hi,.card[data-size=\"6x6\"] .hi{flex-direction:row;align-items:center}\n.card[data-size=\"6x3\"] .hi-act,.card[data-size=\"6x6\"] .hi-act{flex:none}\n\n.sset{display:flex;flex-direction:column;gap:12px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{height:28px;padding:0 10px;border:1px solid var(--line);border-radius:99px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:12px;cursor:pointer;white-space:nowrap}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.help{font-size:11px;color:var(--muted)}\n.card[data-size=\"6x3\"] .sset{display:grid;grid-template-columns:1fr 1fr;gap:8px 14px}\n.card[data-size=\"6x3\"] .sset .note,.card[data-size=\"6x3\"] .sset .help{grid-column:1/-1}\n";
var SORTS=[['stale','久未读优先'],['recent','最近读过优先'],['progress','进度高优先']];

function norm(s){
  s=s||{};
  var sd=Number(s.staleDays);
  return Object.assign({},s,{
    books:Array.isArray(s.books)?s.books:[],
    history:Array.isArray(s.history)?s.history:[],
    staleDays:(Number.isInteger(sd)&&sd>0)?sd:14,
    sort:(s.sort==='recent'||s.sort==='progress')?s.sort:'stale'
  });
}
function toInt(v){
  var t=String(v==null?'':v).trim();
  if(t==='')return null;
  var n=Number(t);
  return Number.isInteger(n)?n:null;
}
function dnum(s){var p=String(s).split('-');return Math.round(Date.UTC(+p[0],+p[1]-1,+p[2])/86400000);}
function agoDays(date,today){return dnum(today)-dnum(date);}
function agoText(n){return n<=0?'今天':n===1?'昨天':n+'天前';}
function pct(cur,total){return total>0?Math.min(100,Math.floor(cur*100/total)):0;}
function ratio(cur,total){return total>0?Math.max(0,Math.min(100,cur*100/total)):0;}
function validDate(v){
  return /^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.UTC(+v.slice(0,4),+v.slice(5,7)-1,+v.slice(8,10)));
}
function daysOf(b,today){
  var r=b.lastRead||b.addedOn;
  return r?Math.max(0,agoDays(r,today)):0;
}
function sortBooks(list,mode,today){
  var a=list.slice();
  a.sort(function(x,y){
    var r=0;
    if(mode==='stale')r=daysOf(y,today)-daysOf(x,today);
    else if(mode==='recent')r=daysOf(x,today)-daysOf(y,today);
    else r=pct(y.current,y.total)-pct(x.current,x.total);
    return r||String(x.title).localeCompare(String(y.title));
  });
  return a;
}
function previewText(total,cur){
  var t=toInt(total);
  var c=String(cur==null?'':cur).trim()===''?0:toInt(cur);
  if(t===null||t<1||c===null||c<0)return '';
  if(c>t)return '当前页码超过了总页数';
  return '进度 '+pct(c,t)+'%（'+c+' / '+t+' 页）'+(c===t?'，保存后移入历史记录':'');
}
function parseDraft(d,today){
  var title=String(d.title||'').trim();
  if(!title)return {err:'请填写书名'};
  var total=toInt(d.total);
  if(total===null||total<1)return {err:'总页数请填不小于 1 的整数'};
  var cur=String(d.current==null?'':d.current).trim()===''?0:toInt(d.current);
  if(cur===null||cur<0)return {err:'当前页码请填不小于 0 的整数'};
  if(cur>total)return {err:'当前页码不能超过总页数（'+total+'）'};
  var date=String(d.date||'').trim();
  if(date){
    if(!validDate(date))return {err:'阅读日期格式不对'};
    if(date>today)return {err:'阅读日期不能晚于今天'};
  }
  return {title:title,total:total,current:cur,date:date};
}
function composeBook(o,p,id,today){
  var last=p.date||((o&&o.lastRead)?o.lastRead:(p.current>0?today:null));
  return {id:id,title:p.title,total:p.total,current:p.current,lastRead:last,addedOn:(o&&o.addedOn)||today};
}
function placeBook(s,b,prev,today){
  var n=norm(s);
  var books=n.books.filter(function(x){return x.id!==b.id;});
  var history=n.history.filter(function(x){return x.id!==b.id;});
  if(b.current>=b.total){
    history.unshift({id:b.id,title:b.title,total:b.total,addedOn:b.addedOn||null,finishedOn:b.lastRead||today,prev:prev||{current:0,lastRead:null}});
  }else{
    books.push(b);
  }
  return Object.assign({},n,{books:books,history:history});
}


function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const size=ctx.size||'3x3';
  const wide=size.charAt(0)==='6';
  const today=day();
  const S=norm(state);
  const view=ui.view||'list';

  function E(tag,attrs,...rest){
    const kids=[];
    rest.forEach(function(c){
      if(Array.isArray(c)){c.forEach(function(x){if(x!=null&&x!==false)kids.push(x);});}
      else if(c!=null&&c!==false)kids.push(c);
    });
    return el(tag,attrs||{},...kids);
  }
  function enter(fn){return function(e){if(e.key==='Enter'){e.preventDefault();fn();}};}
  function go(o){
    Object.assign(ui,{err:'',notice:'',confirm:null},o||{});
    redraw();
  }
  function nu(o){
    return Object.assign({view:'list',id:null,form:null,draft:null,err:'',notice:'',confirm:null,busy:false},o||{});
  }
  function run(fn,next){
    if(ui.busy)return;
    ui.busy=true;
    const fail=function(e){
      ui.busy=false;
      ui.err='保存失败：'+((e&&e.message)||'请稍后重试');
      redraw();
    };
    try{
      Promise.resolve(commit(fn,next)).then(function(ok){if(ok===false)fail();},fail);
    }catch(e){fail(e);}
  }
  function btn(label,onclick,cls,disabled){
    return E('button',{type:'button',class:'btn'+(cls?' '+cls:''),onclick:onclick,disabled:!!disabled},label);
  }

  function openAdd(){go({view:'form',form:{mode:'add'},draft:{title:'',total:'',current:'',date:''}});}
  function openEdit(b){
    go({view:'form',form:{mode:'edit',id:b.id},draft:{title:b.title,total:String(b.total),current:String(b.current),date:b.lastRead||''}});
  }
  function openDetail(b){go({view:'detail',id:b.id,draft:{current:String(b.current),date:today}});}
  function toList(){go({view:'list',id:null,form:null,draft:null});}
  function openHistory(){go({view:'history',draft:null});}
  function openSettings(){go({view:'settings',draft:{stale:String(S.staleDays)}});}

  function saveForm(){
    const f=ui.form||{mode:'add'};
    const isEdit=f.mode==='edit';
    const p=parseDraft(ui.draft||{},today);
    if(p.err){ui.err=p.err;redraw();return;}
    const id=isEdit?f.id:uid();
    const fin=p.current>=p.total;
    run(function(s){
      const n=norm(s);
      const old=isEdit?n.books.find(function(x){return x.id===id;}):null;
      if(isEdit&&!old)return s;
      const b=composeBook(old,p,id,today);
      return placeBook(s,b,old?{current:old.current,lastRead:old.lastRead||null}:null,today);
    },nu(fin?{view:'list',notice:'《'+p.title+'》已读完，已放入历史记录'}
      :isEdit?{view:'detail',id:id,draft:{current:String(p.current),date:today}}
      :{view:'list',notice:'已添加《'+p.title+'》'}));
  }
  function saveProgress(b,toEnd){
    const d=ui.draft||{};
    const p=parseDraft({title:b.title,total:b.total,current:toEnd?String(b.total):d.current,date:d.date||today},today);
    if(p.err){ui.err=p.err;redraw();return;}
    const fin=p.current>=p.total;
    run(function(s){
      const n=norm(s);
      const old=n.books.find(function(x){return x.id===b.id;});
      if(!old)return s;
      const nb=composeBook(old,p,b.id,today);
      return placeBook(s,nb,{current:old.current,lastRead:old.lastRead||null},today);
    },nu(fin?{view:'list',notice:'《'+b.title+'》已读完，已放入历史记录'}
      :{view:'list',notice:'已更新《'+b.title+'》：'+pct(p.current,p.total)+'%'}));
  }
  function delBook(id){
    run(function(s){
      const n=norm(s);
      return Object.assign({},n,{books:n.books.filter(function(x){return x.id!==id;})});
    },nu({view:'list',notice:'已删除这本书'}));
  }
  function delHist(id){
    run(function(s){
      const n=norm(s);
      return Object.assign({},n,{history:n.history.filter(function(x){return x.id!==id;})});
    },nu({view:'history',notice:'已删除这条历史记录'}));
  }
  function restore(id,title){
    run(function(s){
      const n=norm(s);
      const x=n.history.find(function(h){return h.id===id;});
      if(!x)return s;
      const pc=x.prev&&x.prev.current?x.prev.current:0;
      const b={id:x.id,title:x.title,total:x.total,current:Math.max(0,Math.min(pc,x.total-1)),lastRead:(x.prev&&x.prev.lastRead)||null,addedOn:x.addedOn||today};
      return Object.assign({},n,{
        history:n.history.filter(function(h){return h.id!==id;}),
        books:n.books.filter(function(y){return y.id!==id;}).concat([b])
      });
    },nu({view:'history',notice:'《'+title+'》已移回在读'}));
  }
  function saveStale(){
    const v=toInt((ui.draft||{}).stale);
    if(v===null||v<1||v>3650){ui.err='天数请填 1 到 3650 的整数';redraw();return;}
    run(function(s){return Object.assign({},norm(s),{staleDays:v});},nu({view:'settings',draft:{stale:String(v)},notice:'已保存：超过 '+v+' 天未读标为久未读'}));
  }
  function setSort(k){
    run(function(s){return Object.assign({},norm(s),{sort:k});},nu({view:'settings',draft:{stale:String((ui.draft||{}).stale||S.staleDays)}}));
  }


  function barEl(cur,total){
    const fill=E('i');
    fill.style.width=ratio(cur,total)+'%';
    return E('span',{class:'bar',role:'progressbar','aria-valuemin':'0','aria-valuemax':'100','aria-valuenow':String(pct(cur,total))},fill);
  }
  function frame(title,body,foot,back){
    return E('div',{class:'rp pg'},
      E('div',{class:'hd'},
        E('button',{type:'button',class:'ibtn',onclick:back,'aria-label':'返回'},'‹'),
        E('div',{class:'ttl'},title)),
      E('div',{class:'bd'},body),
      ui.err?E('div',{class:'err',role:'alert'},ui.err):null,
      foot?E('div',{class:'ft'},foot):null);
  }

  function bookItem(b){
